    private string name;
    private double balance;

    public BankAccount(string name, double balance)
    {
        this.name = name;
        this.balance = balance;
    }

    public string ShowUserNameAndBalance()
    {
        string formattedBalance;

        if (balance < 0)
        {
            // Negative balance: show the sign before the dollar sign
            formattedBalance = $"{Math.Abs(balance):F2}";
            // Add minus sign before the dollar sign
            formattedBalance = $"{Math.Abs(balance):F2} $-{formattedBalance}";
        }
        else
        {
